style.css:
@-moz-document domain("instagram.com") {
/* Entire post container */
  article {
    background: #000 !important; /* pure black */
    border-radius: 0px !important; /* remove rounded edges to make it plate-like */
    overflow: hidden !important; /* ensure no internal divisions pop out */
    box-shadow: none !important;
    border: none !important;
  }

  /* Merge all inner sections like captions, likes, comments */
  article div, article section, article ul, article li {
    background: #000 !important; /* force pure black */
    color: #fff !important; /* readable text */
    border: none !important; /* remove lines/divisions */
    box-shadow: none !important;
  }

  /* Remove hover or focus effects inside posts */
  article *:hover, article *:focus {
    background: #000 !important;
  }

  /* Header, sidebars, main feed */
  header, aside, main {
    background: #000 !important;
    color: #fff !important;
  }

  /* Stories bar */
  header div[role="presentation"] {
    background: #000 !important;
  }

  /* Text everywhere readable */
  span, p, h1, h2, h3, h4, h5, h6, a {
    color: #fff !important;
  }
}
